/**
 * The night side's city lights (ADR-IMPL-035, amended 13 Oct 2026): every place of 100,000 people or more in Natural
 * Earth's populated places (public domain), generated by packages/ui/scripts/globe-city-lights.ts — never edit the JSON
 * by hand. A city's light grows with its population and shows only where the sun is down: none at the horizon, full
 * past −6° (civil dusk). The map works out each city's dusk on the device from the sun's position, so the points are
 * sent to it once and only the sun moves every minute.
 */
import type { FeatureCollection, Point } from "geojson";

import data from "./city-lights/places.json";

export const CITY_LIGHTS = {
  /** The sun's altitude, degrees, at which a city's light is full, and above which it is off. */
  fullBelowDeg: -6,
  offAboveDeg: 0,
  /** Opacity at full dark: a town of 100,000 people, then up to the largest cities. */
  weight: { min: 0.38, perDecade: 0.22, max: 0.9 },
  /** Radius in points at the globe's resting zoom (blurred to a glow), growing with the city. */
  radius: { min: 0.8, perDecade: 0.9, max: 2.6 },
} as const;

/** Per city: sin and cos of its latitude and its longitude in radians — what its dusk needs — then its light. */
export type CityLightProps = { s: number; c: number; l: number; w: number; r: number };

const DEG = Math.PI / 180;
const clamp = (v: number, lo: number, hi: number) => Math.min(hi, Math.max(lo, v));
const four = (v: number) => Math.round(v * 1e4) / 1e4;

let built: FeatureCollection<Point, CityLightProps> | null = null;

/** The lights as one GeoJSON source, built once. `p` in the data is log10(population / 100,000). */
export function cityLightFeatures(): FeatureCollection<Point, CityLightProps> {
  if (built) return built;
  const { weight, radius } = CITY_LIGHTS;
  built = {
    type: "FeatureCollection",
    features: data.places.map(([lng = 0, lat = 0, p = 0]) => ({
      type: "Feature",
      geometry: { type: "Point", coordinates: [lng, lat] },
      properties: {
        s: four(Math.sin(lat * DEG)),
        c: four(Math.cos(lat * DEG)),
        l: four(lng * DEG),
        w: four(clamp(weight.min + weight.perDecade * p, weight.min, weight.max)),
        r: four(clamp(radius.min + radius.perDecade * p, radius.min, radius.max)),
      },
    })),
  };
  return built;
}
